window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/natureza_2025.js"]=[{"title":"Adsorção e área de contato","steps":["A figura mostra que a ativação cria poros de tamanhos variados. As paredes internas desses poros também entram em contato com as impurezas.","Adsorção é a retenção de partículas na superfície do material, não sua absorção para o interior de uma solução. Uma área superficial maior oferece mais locais de interação.","Assim, para comparar a eficiência descrita, interessa a superfície disponível: D. Não basta comparar o tamanho externo dos grãos."],"alternatives":{"A":"A massa isoladamente não explica a vantagem: massas iguais de carvões com porosidades diferentes podem oferecer áreas muito distintas.","B":"A dureza mede resistência a deformações e riscos; não determina a quantidade de locais superficiais de adsorção.","C":"A densidade relaciona massa e volume. O mecanismo apresentado depende diretamente da superfície exposta, não dessa razão.","D":"Os numerosos poros ampliam a superfície de contato e os locais em que contaminantes podem ficar adsorvidos.","E":"A condutividade descreve transporte de calor ou carga elétrica; não é o mecanismo de remoção mostrado."},"takeaway":"Em adsorção, procure área superficial e porosidade; não confunda adsorver com absorver.","key":"natureza:N619","area":"natureza","year":2025,"number":91,"answer":"D","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Genes inseridos não substituem todo o genoma","steps":["Identifique doador e receptor: S. elongatus fornece os genes do ciclo circadiano; E. coli recebe esses genes.","A bactéria receptora continua precisando de seus próprios genes metabólicos. Inserir um conjunto de genes não significa trocar todo o genoma.","O organismo modificado reúne metabolismo de E. coli e ciclo circadiano de S. elongatus: D."],"alternatives":{"A":"Ignora os genes circadianos transferidos, explicitamente presentes no organismo modificado.","B":"E. coli era não circadiana; os genes inseridos não se originaram nela. Também faltam seus genes metabólicos.","C":"Inverte os papéis: não se transferiu todo o metabolismo de S. elongatus nem havia ciclo circadiano original em E. coli.","D":"Combina corretamente o conjunto circadiano do doador com os genes metabólicos preservados no receptor.","E":"Atribui um ciclo circadiano original a E. coli, contrariando sua caracterização no enunciado."},"takeaway":"Em transgenia, separe o gene introduzido das características que o receptor já possuía.","key":"natureza:N188","area":"natureza","year":2025,"number":92,"answer":"D","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Impermeabilização das penas","steps":["Localize o problema observado: as penas ficaram encharcadas, aumentando a dificuldade de flutuação.","A secreção oleosa da glândula uropigial é espalhada sobre as penas durante o cuidado corporal e contribui para sua impermeabilização.","Reduzir essa secreção favorece a retenção de água nas penas. A relação causal pedida está em C."],"alternatives":{"A":"O papo se relaciona ao armazenamento de alimento, não à produção da secreção que protege as penas da água.","B":"A renovação das penas não é a estrutura secretora cuja redução explica diretamente o encharcamento descrito.","C":"A menor secreção oleosa reduz a impermeabilização das penas, ligando a alteração ao problema de flutuação.","D":"A membrana natatória auxilia a propulsão na água; sua formação não explica por que as penas se encharcam.","E":"Ossos pneumáticos se relacionam à leveza do esqueleto; o mecanismo observado envolve a superfície das penas."},"takeaway":"Parta do sintoma específico e associe-o à função do órgão, sem escolher apenas uma adaptação aquática qualquer.","key":"natureza:N266","area":"natureza","year":2025,"number":93,"answer":"C","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Limite de potência e ordem das atividades","steps":["A régua admite Pmáx = UI = 110 × 20 = 2 200 W. Computador e ar já consomem 250 + 1 100 = 1 350 W.","Com a impressora: 1 350 + 660 = 2 010 W, abaixo do limite. Com a cafeteira: 1 350 + 900 = 2 250 W, acima dele.","A segunda tentativa rompe o fusível. Mesmo que a luminária isoladamente coubesse no limite, ela vem depois da interrupção: apenas uma atividade, D."],"alternatives":{"A":"Quatro atividades exigiriam que a régua continuasse funcionando após a cafeteira exceder 2 200 W.","B":"Três atividades ignoram a interrupção definitiva na segunda tentativa, antes de ligar a luminária.","C":"Duas atividades só seriam possíveis se a cafeteira não rompesse o fusível, mas sua soma é 2 250 W.","D":"Somente imprimir é possível antes do rompimento. A ordem das tentativas faz parte dos dados do problema.","E":"A impressora ainda permite corrente 2 010/110 ≈ 18,3 A; portanto ao menos a primeira atividade funciona."},"takeaway":"Em problemas com fusível, calcule o limite e siga a sequência: não continue depois do primeiro rompimento.","key":"natureza:N321","area":"natureza","year":2025,"number":94,"answer":"D","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vacina: antígeno e resposta ativa","steps":["O esquema apresenta vírus inativados aplicados como antígenos, seguidos da produção de moléculas de defesa no organismo.","O antígeno estimula a resposta imune adaptativa. Linfócitos B originam plasmócitos produtores de anticorpos, proteínas capazes de neutralizar o vírus.","Logo a vacina induz a produção dessas proteínas: D. Não se trata de fornecer anticorpos prontos, como na imunização passiva."],"alternatives":{"A":"O antígeno não mata o vírus por ligação direta: ele é reconhecido pelo sistema imune, que produz a resposta.","B":"Aglutinação pode envolver anticorpos, mas a alternativa atribui ao antígeno o papel de agente que aglutina o vírus.","C":"Imunoglobulinas prontas caracterizam imunização passiva, não o antígeno viral utilizado nessa vacina.","D":"A apresentação do antígeno induz a produção de anticorpos, proteínas neutralizadoras representadas no esquema.","E":"A resposta pode aumentar e renovar a produção de anticorpos; não se limita a manter uma quantidade anterior."},"takeaway":"Vacina estimula uma resposta ativa; soro fornece anticorpos já produzidos.","key":"natureza:N291","area":"natureza","year":2025,"number":97,"answer":"D","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Competição e invasão biológica","steps":["O capim-gordura foi introduzido fora de sua região de origem e possui elevada capacidade de expansão no Cerrado.","A competição por luz, água, espaço e nutrientes pode reduzir o estabelecimento de plantas nativas e simplificar a comunidade.","O efeito sustentado pelo texto é a diminuição de espécies nativas: D. Ser exótica não basta para ser invasora, mas a agressividade competitiva descrita sustenta o risco."],"alternatives":{"A":"A introdução não implica diversificação equilibrada de nichos; a competição intensa pode diminuir a diversidade nativa.","B":"Assoreamento envolve transporte e deposição de sedimentos. O texto destaca competição entre plantas, não esse processo.","C":"A alteração da infiltração não é a consequência diretamente fundamentada pelos dados de expansão competitiva.","D":"A expansão da invasora pode excluir ou reduzir populações nativas, comprometendo a biodiversidade do Cerrado.","E":"Não há evidência de redução de queimadas. Gramíneas invasoras podem inclusive alterar o combustível disponível ao fogo."},"takeaway":"Espécie exótica competitiva pode reduzir biodiversidade; introdução de espécie não é sinônimo de enriquecimento ecológico.","key":"natureza:N002","area":"natureza","year":2025,"number":98,"answer":"D","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ambientes semelhantes e adaptações","steps":["O lagarto de referência vive em deserto, ambiente com restrição hídrica e períodos de pouca disponibilidade alimentar.","A pergunta pede uma hipótese por semelhança ambiental, não a afirmação de que todo lagarto brasileiro possui o mesmo hormônio.","Entre os ambientes listados, a Caatinga, com clima semiárido e forte sazonalidade, é a comparação mais adequada: C."],"alternatives":{"A":"O Cerrado possui estação seca, mas a Caatinga oferece a correspondência mais direta com a aridez enfatizada.","B":"Os Pampas são campos do Sul e não correspondem ao ambiente semiárido tomado como referência.","C":"A Caatinga apresenta restrições e sazonalidade compatíveis com a hipótese de adaptações semelhantes.","D":"A restinga é uma formação costeira; suas condições não são a comparação principal com um deserto continental.","E":"O Pantanal tem regime de inundações, contrastando com a aridez central à comparação solicitada."},"takeaway":"Em analogias adaptativas, compare a pressão ambiental e mantenha a conclusão como hipótese, não certeza universal.","key":"natureza:N189","area":"natureza","year":2025,"number":99,"answer":"C","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Água destilada e sais dissolvidos","steps":["O processo descrito remove sais dissolvidos e gera água empregada em laboratórios e baterias.","Na destilação, a água vaporiza e o vapor é condensado; os sais não voláteis permanecem no recipiente inicial.","A denominação correspondente é água destilada: D. Os demais nomes indicam composições distintas, não água desmineralizada por esse processo."],"alternatives":{"A":"Água dura contém concentrações relevantes de íons cálcio e magnésio, oposto à remoção de sais descrita.","B":"Água pesada contém proporção elevada de deutério; a expressão se refere a isótopos, não à retirada de sais.","C":"Água sanitária é solução com hipoclorito, usada como desinfetante, e não água purificada para baterias.","D":"Água destilada é obtida por vaporização e condensação, separando a água dos sais não voláteis.","E":"Água oxigenada é uma solução de peróxido de hidrogênio, substância diferente da água destilada."},"takeaway":"Identifique a composição química indicada por cada nome; nomes comerciais não são sinônimos de pureza.","key":"natureza:N620","area":"natureza","year":2025,"number":100,"answer":"D","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pupila dilatada e reflexão do flash","steps":["Em pouca iluminação, a pupila se dilata para aumentar a entrada de luz no olho.","O flash pode então iluminar mais intensamente o interior do olho. A luz refletida na região vascularizada produz a aparência vermelha.","A combinação correta é pupila dilatada e maior chegada de luz à retina: A. Não é necessário supor uma seleção de azul e verde."],"alternatives":{"A":"A dilatação aumenta a abertura e a entrada de luz, favorecendo o reflexo vermelho descrito.","B":"No escuro a tendência é dilatar, não retrair a pupila. A entrada não é exclusivamente de luz vermelha.","C":"A retração contraria a adaptação ao escuro; atribuir seletividade vermelha aos bastonetes também não explica o efeito.","D":"A pupila não seleciona especificamente azul e verde; a alternativa ainda inverte sua resposta ao escuro.","E":"A dilatação amplia a entrada total de luz, e não reduz seletivamente essas cores nos bastonetes."},"takeaway":"Separe controle de abertura da pupila de percepção de cores e de reflexão no interior do olho.","key":"natureza:N540","area":"natureza","year":2025,"number":101,"answer":"A","subject":"Física","topic":"Óptica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Toxina termoestável e contaminação do filé","steps":["A tetrodotoxina está concentrada em gônadas e vísceras, enquanto a iguaria utiliza o filé.","Rompê-las durante o preparo pode transferir toxina ao músculo. A medida diretamente apoiada pelo enunciado é evitar esse rompimento.","A toxina é termoestável: aquecer não assegura sua destruição. Assim, E é a resposta do item, sem transformar o procedimento em orientação doméstica de consumo seguro."],"alternatives":{"A":"O texto não informa que criar o peixe em cativeiro impeça a presença da toxina; essa conclusão não pode ser presumida.","B":"O tipo de captura com redes não impede a contaminação do filé durante a retirada das vísceras.","C":"Cozimento ou fritura não resolvem o problema descrito, pois a toxina é explicitamente termoestável.","D":"Higiene combate contaminações, mas não elimina uma toxina já presente nos órgãos do próprio peixe.","E":"Evitar romper os órgãos internos reduz a transferência da toxina para a parte consumida, como pede o texto."},"takeaway":"Termoestável significa resistente ao calor; alimento tóxico não se torna necessariamente seguro por cozimento.","key":"natureza:N190","area":"natureza","year":2025,"number":102,"answer":"E","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Remover CO₂ é diferente de evitar emissões","steps":["O comando pede uma ação que retire gás já presente na atmosfera, e não apenas reduza novas emissões.","Árvores fixam carbono pela fotossíntese, incorporando-o à matéria orgânica. O crescimento e a conservação da biomassa podem ampliar seu armazenamento.","Plantar mais árvores atende diretamente ao verbo remover: A. Energia limpa e menor consumo de fósseis são importantes, mas atuam principalmente evitando emissões."],"alternatives":{"A":"O crescimento das árvores incorpora carbono atmosférico à biomassa por fotossíntese, correspondendo à remoção pedida.","B":"Usinas eólicas podem substituir fontes emissoras, mas não retiram diretamente o CO₂ que já está na atmosfera.","C":"A energia solar reduz a necessidade de fontes fósseis; sua geração não constitui captura direta do gás.","D":"Manter combustíveis no solo evita novas emissões por queima, sem remover o carbono atmosférico já acumulado.","E":"Produzir menos resíduos pode diminuir emissões, mas não é o mecanismo de captura diretamente solicitado."},"takeaway":"Sublinhe o verbo do comando: remover um poluente e deixar de emiti-lo são intervenções diferentes.","key":"natureza:N003","area":"natureza","year":2025,"number":104,"answer":"A","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Poluição térmica e oxigênio dissolvido","steps":["O problema é a transferência de calor ao ambiente aquático, não um vazamento do circuito nuclear.","A elevação da temperatura da água diminui a solubilidade do oxigênio gasoso. Isso reduz sua disponibilidade para a respiração de organismos aquáticos.","A consequência diretamente vinculada ao aquecimento é E. Não é preciso supor liberação de combustível ou radioatividade."],"alternatives":{"A":"A queda do pH não decorre necessariamente do simples aquecimento da água; exigiria outro mecanismo químico.","B":"O enunciado não descreve emissão de gases poluentes; o impacto focalizado é térmico.","C":"Não há indicação de vazamento de combustível no circuito de refrigeração para a água natural.","D":"Poluição térmica não é sinônimo de contaminação radioativa, nem implica liberação de radionuclídeos.","E":"A água mais quente dissolve menos oxigênio, comprometendo organismos que dependem desse gás dissolvido."},"takeaway":"Usina nuclear pode causar impacto térmico sem acidente radioativo. Identifique o mecanismo efetivamente descrito.","key":"natureza:N606","area":"natureza","year":2025,"number":105,"answer":"E","subject":"Física","topic":"Física moderna e nuclear","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Traduzindo a notação antiga","steps":["O símbolo Az substitui N, sem mudar a quantidade de átomos: ácido nítrico atual HNO₃ torna-se HAzO₃.","Cloreto de cálcio combina Ca²⁺ e Cl⁻. São necessários dois cloretos por cálcio, formando CaCl₂.","O par correto é HAzO₃ e CaCl₂, alternativa A. Símbolo de um elemento e índice estequiométrico exercem funções diferentes."],"alternatives":{"A":"Conserva os índices do ácido nítrico e equilibra corretamente as cargas do cálcio e do cloreto.","B":"HAz₃O troca os índices de nitrogênio e oxigênio; Ca₂Cl não corresponde à neutralidade do sal.","C":"H₃AzO₄ não representa ácido nítrico; CaCl também não equilibra Ca²⁺ com Cl⁻.","D":"Além de errar a fórmula do ácido, K indica potássio, não cálcio; KCl₂ também não é o sal pedido.","E":"HAzO₂ corresponderia à notação do ácido nitroso; KCl é cloreto de potássio, não de cálcio."},"takeaway":"Trocar um símbolo histórico não autoriza trocar os índices ou a identidade dos demais elementos.","key":"natureza:N853","area":"natureza","year":2025,"number":106,"answer":"A","subject":"Química","topic":"Estrutura atômica e periodicidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Codominância: 1 : 2 : 1","steps":["Na figura, um parental apresenta pontos e o outro, uma faixa. A primeira geração expressa simultaneamente os dois padrões.","Represente os alelos por P e F: PP × FF produz PF. Ao cruzar PF × PF, obtêm-se PP, PF, PF e FF.","A prole esperada tem 1/4 apenas pontos, 1/2 pontos e faixa e 1/4 apenas faixa, em ambos os sexos: imagem E."],"alternatives":{"A":"Mostrar apenas insetos com pontos elimina os genótipos PF e FF esperados no cruzamento dos heterozigotos.","B":"Mostrar somente a faixa também elimina três quartos das combinações previstas no quadro de Punnett.","C":"Todos com os dois padrões descrevem a primeira geração parental, não a segregação do cruzamento PF × PF.","D":"A proporção 1:1 de fenótipos parentais omite os heterozigotos, que expressam pontos e faixa juntos.","E":"As quatro figuras representam um só pontos, um só faixa e dois com ambos: proporção fenotípica 1:2:1."},"takeaway":"Na codominância o heterozigoto expressa os dois padrões, e a F₂ pode ter três fenótipos.","key":"natureza:N099","area":"natureza","year":2025,"number":107,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Atrito cinético não acompanha a força aplicada","steps":["Considere apenas o trecho inclinado, como pede o comando. A caixa continua deslizando durante todo esse trecho.","A força aplicada é paralela ao plano e não modifica a normal. Com inclinação e rugosidade constantes, N = mg cos θ e Fat = μcin N são constantes.","Reduzir a força de tração pode alterar a aceleração, mas não essa força de atrito no modelo do item. O gráfico horizontal é C."],"alternatives":{"A":"A queda e a subida de atrito indicadas não decorrem de μ e normal constantes no plano inclinado.","B":"O pico seguido de redução não representa o atrito cinético constante durante o trecho solicitado.","C":"A reta horizontal representa μcin mg cos θ constante, mesmo quando o trabalhador muda a tração.","D":"O atrito não diminui até zero por o trabalhador reduzir a força; a caixa continua em movimento.","E":"A subida e queda do gráfico confundem a variação da força aplicada com a força de atrito."},"takeaway":"Antes de desenhar Fat, verifique μ, normal e se há deslizamento. Velocidade menor não implica atrito menor.","key":"natureza:N372","area":"natureza","year":2025,"number":108,"answer":"C","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reconhecendo uma descarboxilação","steps":["Compare reagente e produto: o ácido anacárdico perde o grupo carboxila ligado ao anel, enquanto a hidroxila fenólica permanece.","O esquema explicita a liberação de CO₂ durante o aquecimento. Essa perda de carboxila caracteriza descarboxilação.","A resposta é E. A cadeia lateral e o anel aromático continuam presentes, sem adição de hidrogênio nem formação de éster."],"alternatives":{"A":"Hidrólise envolve ruptura com participação de água, o que não representa a transformação mostrada.","B":"Fenilação introduziria um grupo fenila; o anel já existe no reagente e não está sendo acrescentado.","C":"Esterificação produziria um éster, mas o produto mantém o fenol e elimina a carboxila como CO₂.","D":"Hidrogenação adiciona hidrogênio a uma estrutura; não é a perda de CO₂ explicitada no esquema.","E":"A remoção da carboxila com liberação de dióxido de carbono define a descarboxilação observada."},"takeaway":"Compare grupos funcionais antes de escolher o nome da reação; CO₂ liberado é uma pista importante.","key":"natureza:N700","area":"natureza","year":2025,"number":109,"answer":"E","subject":"Química","topic":"Reações orgânicas e polímeros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cinco meias-vidas do cobalto-60","steps":["Conte os intervalos: n = 26,5/5,3 = 5 meias-vidas.","A cada intervalo resta metade: 2 → 1 → 0,5 → 0,25 → 0,125 → 0,0625 mg.","Equivalentemente, m = 2/2⁵ = 0,0625 mg, valor mais próximo de 0,06 mg: E. O decaimento é exponencial, não linear."],"alternatives":{"A":"2,00 mg seria a massa inicial, sem qualquer decaimento durante os 26,5 anos.","B":"1,00 mg corresponde a apenas uma meia-vida, isto é, 5,3 anos, não cinco intervalos.","C":"0,40 mg resulta de dividir a massa por cinco, procedimento incompatível com sucessivas metades.","D":"0,13 mg aproxima a massa após quatro meias-vidas, 0,125 mg; ainda falta mais uma divisão por dois.","E":"0,06 mg aproxima corretamente 0,0625 mg, a massa restante após cinco meias-vidas."},"takeaway":"Tempo dividido pela meia-vida fornece o expoente de 2, não o divisor direto da massa.","key":"natureza:N607","area":"natureza","year":2025,"number":110,"answer":"E","subject":"Física","topic":"Física moderna e nuclear","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Biodigestão e prevenção da eutrofização","steps":["A etapa 4 destina as sobras à fertilização do solo, em vez de descartá-las diretamente em corpos de água.","Resíduos ricos em nutrientes podem enriquecer a água, favorecer florações e elevar o consumo de oxigênio na decomposição.","Esse processo é a eutrofização: B. O uso do fertilizante também exige manejo adequado para evitar escoamento excessivo de nutrientes."],"alternatives":{"A":"Bioacumulação é a retenção de substâncias em organismos; o esquema enfatiza o destino de resíduos nutrientes.","B":"Evitar o lançamento de nutrientes e matéria orgânica na água ajuda a prevenir eutrofização e falta de oxigênio.","C":"Destruição do ozônio estratosférico envolve outras substâncias e mecanismos, não o destino do adubo mostrado.","D":"Inversão térmica é um fenômeno atmosférico de estabilidade do ar; não decorre desse manejo de sobras.","E":"Chuva ácida se relaciona principalmente a óxidos de enxofre e nitrogênio atmosféricos, não ao processo focalizado."},"takeaway":"Resíduo com nutrientes na água remete a eutrofização; não confunda com acúmulo de toxinas.","key":"natureza:N004","area":"natureza","year":2025,"number":111,"answer":"B","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Vitamina A e visão em baixa luminosidade","steps":["O arroz foi enriquecido em betacaroteno, que pode ser convertido pelo organismo em vitamina A.","A vitamina A participa da formação de pigmentos visuais. Sua deficiência prejudica a adaptação à pouca luz.","O problema associado é cegueira noturna, alternativa D. Identificar a vitamina permite descartar carências de outras vitaminas."],"alternatives":{"A":"Hemofilia envolve alterações da coagulação, geralmente hereditárias, não deficiência de vitamina A.","B":"Escorbuto é associado à falta de vitamina C, necessária à síntese adequada de colágeno.","C":"Raquitismo está relacionado à mineralização óssea e frequentemente à deficiência de vitamina D.","D":"A deficiência de vitamina A pode causar dificuldade de enxergar com pouca iluminação, chamada cegueira noturna.","E":"Anemia perniciosa relaciona-se à deficiência de vitamina B12 por problemas de absorção, não à falta de vitamina A."},"takeaway":"Associe cada vitamina à sua função, em vez de decorar apenas uma lista de nomes de doenças.","key":"natureza:N100","area":"natureza","year":2025,"number":112,"answer":"D","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Carga negativa desvia contra o campo","steps":["Na figura 2, o campo elétrico aponta para cima e o feixe de elétrons tem velocidade inicial horizontal.","A força é F = qE. Como a carga do elétron é negativa, sua força elétrica aponta para baixo, em sentido oposto ao campo.","O feixe sofre desvio para a parte inferior da tela, ponto 2. A resposta é B; não se aplica a regra de força magnética a esse campo elétrico."],"alternatives":{"A":"O ponto 1 está acima do centro: seria o sentido da força sobre uma carga positiva nesse campo.","B":"O ponto 2 está abaixo do centro, no sentido da força elétrica sobre os elétrons.","C":"O ponto 3 indica desvio lateral, incompatível com o campo vertical representado.","D":"O ponto 4 também é lateral; não corresponde ao sentido oposto ao vetor campo elétrico.","E":"O ponto 5 central exigiria ausência de desvio, mas há força elétrica vertical sobre o feixe."},"takeaway":"Para campo elétrico, use F = qE; a carga negativa inverte o sentido, sem produto vetorial.","key":"natureza:N322","area":"natureza","year":2025,"number":113,"answer":"B","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ressonância depende de frequência","steps":["A questão afasta explicitamente a intensidade como explicação central para a quebra das taças.","Um objeto possui frequências naturais de vibração. Uma excitação sonora próxima de uma delas pode transferir energia eficientemente e ampliar sua oscilação.","Esse fenômeno é a ressonância; a característica decisiva é a frequência da voz: B. Intensidade suficiente ajuda a fornecer energia, mas não substitui a condição de frequência."],"alternatives":{"A":"Reflexão é o retorno da onda numa interface; não explica a amplificação seletiva de vibração da taça.","B":"A coincidência entre frequência de excitação e frequência natural caracteriza ressonância e pode produzir grande amplitude.","C":"Interferência é superposição de ondas; a velocidade de propagação não é o ajuste seletivo pedido.","D":"O fenômeno está nomeado corretamente, mas timbre descreve a composição da onda, não a condição central de ressonância.","E":"A reflexão não é o fenômeno buscado, e a amplitude está ligada à intensidade que o comando afasta como explicação central."},"takeaway":"Ressonância combina frequência de excitação e frequência natural; não é simplesmente fazer um som muito forte.","key":"natureza:N452","area":"natureza","year":2025,"number":114,"answer":"B","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Oxidação de álcool secundário","steps":["Conte os carbonos do borneol representado: são dez. Sua fórmula é C₁₀H₁₈O, com uma única hidroxila.","A oxidação de álcool secundário a cetona retira dois hidrogênios: um do grupo OH e outro do carbono que o porta. O oxigênio permanece na molécula.","A cânfora resultante é C₁₀H₁₆O: C. Não se acrescenta um segundo oxigênio para transformar OH em carbonila."],"alternatives":{"A":"C₉H₁₆O perde indevidamente um carbono; essa oxidação conserva o esqueleto carbônico.","B":"C₉H₁₇O também erra o número de carbonos e a contagem de hidrogênios da cetona formada.","C":"C₁₀H₁₆O conserva dez carbonos e um oxigênio, com perda de dois hidrogênios na oxidação.","D":"C₁₀H₁₆O₂ acrescenta um oxigênio que não é necessário à conversão do álcool em cetona.","E":"C₁₀H₁₈O₂ não retira os dois hidrogênios da oxidação e ainda acrescenta um oxigênio."},"takeaway":"Álcool secundário → cetona: mesmo esqueleto e mesmo número de oxigênios, com perda de H₂ na molécula orgânica.","key":"natureza:N672","area":"natureza","year":2025,"number":115,"answer":"C","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Condições restritas e endemismo","steps":["O texto destaca solos ácidos, rasos, pobres e muito quentes, que funcionam como filtros ambientais.","As comunidades têm muitas espécies com distribuição restrita. Espécies limitadas a uma região são denominadas endêmicas.","Logo C traduz a característica biogeográfica solicitada. Endemismo não significa necessariamente abundância ou dominância local."],"alternatives":{"A":"Exótica é uma espécie fora de sua distribuição natural; não é o termo para distribuição natural restrita.","B":"Migratórias realizam deslocamentos regulares; o texto destaca adaptação local e distribuição limitada.","C":"Endêmicas têm ocorrência natural restrita a determinada região, compatível com a descrição das cangas.","D":"Dominância trata de abundância ou influência na comunidade, não de restrição geográfica.","E":"Generalistas toleram ampla variedade de recursos e condições; não descrevem a especialização destacada."},"takeaway":"Endêmica refere-se a onde a espécie ocorre; dominante, a sua importância ou abundância na comunidade.","key":"natureza:N005","area":"natureza","year":2025,"number":116,"answer":"C","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Equilíbrio da cloração do titânio","steps":["Leia a equação: TiO₂(s) + 2 Cl₂(g) ⇌ TiCl₄(g) + O₂(g), com ΔH positivo.","Aumentar a pressão parcial de Cl₂ adiciona reagente gasoso e favorece seu consumo no sentido dos produtos.","O total de mols gasosos é dois em cada lado; pressão total isoladamente não favorece um lado no modelo usual. A medida correta é D."],"alternatives":{"A":"Existem dois mols gasosos em cada lado. Uma compressão uniforme não favorece a produção de TiCl₄ por diferença de mols.","B":"A reação direta é endotérmica; diminuir a temperatura favorece o sentido inverso, reduzindo a formação desejada.","C":"O₂ é produto. Aumentar sua pressão parcial favorece o consumo dos produtos, deslocando para a esquerda.","D":"Cl₂ é reagente: elevar sua pressão parcial desloca o equilíbrio para a direita, formando mais TiCl₄.","E":"A atividade do sólido puro TiO₂ permanece constante enquanto ele está presente; variar sua quantidade não é a medida pedida."},"takeaway":"No equilíbrio, conte apenas espécies gasosas para efeitos de compressão e não inclua sólidos puros na expressão de K.","key":"natureza:N794","area":"natureza","year":2025,"number":117,"answer":"D","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pressão máxima de uma pilha","steps":["Para uma pilha uniforme com base A, m = ρAh e P = mg/A. Substituindo, P = ρgh.","Com Pmáx = 10⁴ Pa, ρ = 1 250 kg/m³ e g = 10 m/s², h = 10 000/(1 250 × 10).","Resulta h = 0,80 m: C. Os 50 m² cancelam, pois a massa armazenada também cresce com a área ocupada."],"alternatives":{"A":"0,16 m produziria apenas 2 000 Pa, ficando bem abaixo do limite máximo dado.","B":"0,50 m produziria 6 250 Pa; é permitido, mas não é a altura máxima solicitada.","C":"0,80 m produz 1 250 × 10 × 0,80 = 10 000 Pa, exatamente o limite da laje.","D":"1,60 m produziria 20 000 Pa, o dobro da pressão admissível.","E":"8,00 m produziria 100 000 Pa, dez vezes o limite indicado."},"takeaway":"Quando massa e área variam juntas numa pilha uniforme, a pressão depende de ρgh, não da área total.","key":"natureza:N566","area":"natureza","year":2025,"number":118,"answer":"C","subject":"Física","topic":"Hidrostática e fluidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Associação de geradores reais","steps":["Cada placa tem força eletromotriz 40 V e tensão útil 34 V a 7,5 A. Sua resistência interna é r = (40 − 34)/7,5 = 0,8 Ω.","Duas placas em série forneceriam 68 V úteis; três fornecem 102 V, dentro de 95–105 V. Portanto são necessárias três em série.","No equivalente, somam-se forças eletromotrizes e resistências: εeq = 120 V e req = 2,4 Ω. Essa é a figura B; 102 V é a tensão nos terminais, não a força eletromotriz."],"alternatives":{"A":"136 V toma quatro tensões úteis como força eletromotriz; quatro placas também ultrapassam a tensão de operação permitida.","B":"O equivalente de três placas em série tem ε = 3 × 40 = 120 V e r = 3 × 0,8 = 2,4 Ω.","C":"A força eletromotriz 120 V está correta, mas 5,3 Ω não é a soma das três resistências internas.","D":"102 V é a tensão útil da associação a 7,5 A, e não a força eletromotriz do gerador equivalente.","E":"Confunde a tensão útil com a força eletromotriz e ainda apresenta resistência interna incompatível."},"takeaway":"Gerador real: U = ε − ri. Some ε e r em série, não confunda tensão útil com tensão em circuito aberto.","key":"natureza:N323","area":"natureza","year":2025,"number":119,"answer":"B","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Tempo de interrupção do feixe","steps":["O feixe tem 15 cm de diâmetro e o perfil do invasor, 20 cm. Para atravessá-lo completamente, a distância relevante é 35 cm = 0,35 m.","O movimento mais rápido da figura é 5,0 m/s. Ele produz a menor duração de interrupção: t = 0,35/5 = 0,07 s.","Convertendo, 0,07 s = 70 ms: B. O receptor precisa responder nesse intervalo ou mais rapidamente para detectar também essa passagem."],"alternatives":{"A":"30 ms usa apenas os 15 cm do feixe a 5 m/s, omitindo os 20 cm de espessura do corpo.","B":"70 ms resulta de (0,15 + 0,20)/5 e corresponde ao menor intervalo de travessia completa entre os movimentos.","C":"300 ms é muito superior ao intervalo de 70 ms da passagem mais rápida e não a garante.","D":"400 ms também excede o menor tempo de interrupção; não detectaria necessariamente o movimento a 5 m/s.","E":"700 ms corresponde a 0,35/0,5, isto é, ao movimento mais lento, não ao limitante mais rápido."},"takeaway":"Para passagem completa de um corpo por uma faixa, some suas larguras antes de dividir pela velocidade.","key":"natureza:N373","area":"natureza","year":2025,"number":120,"answer":"B","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Indução eletromagnética e aquecimento","steps":["A bobina produz campo magnético variável, que modifica o fluxo magnético através do material condutor da panela.","Pela indução eletromagnética, surgem correntes no fundo da panela. A resistência elétrica dissipa energia dessas correntes em calor.","Esse aquecimento por efeito Joule está descrito em D. Não é necessário aquecer o ar ou transmitir primeiro calor através do vidro."],"alternatives":{"A":"A simples imantação não descreve o mecanismo de correntes induzidas e dissipação elétrica enfatizado.","B":"Não é um transporte mecânico de átomos de ferro que aquece a panela; há indução de correntes elétricas.","C":"O mecanismo não consiste em emitir radiação que aquece através do vidro, mas em induzir correntes na panela.","D":"O campo variável induz correntes no fundo condutor; sua dissipação resistiva produz o efeito Joule.","E":"Convecção transporta calor por movimento de fluido; não é o mecanismo de indução do fogão."},"takeaway":"Campo magnético variável → fluxo variável → corrente induzida → dissipação em calor.","key":"natureza:N586","area":"natureza","year":2025,"number":122,"answer":"D","subject":"Física","topic":"Magnetismo e indução","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Questão anulada: doação de elétrons na fotossíntese","steps":["O gabarito oficial do caderno azul registra esta questão como anulada. Não há letra oficial e ela não deve entrar no cálculo de acerto.","Para estudar o conteúdo: na fotossíntese oxigênica, a água fornece elétrons; sua oxidação permite liberar O₂. Na anoxigênica descrita, H₂S atua como doador de elétrons.","A relação didática é entre doadores de elétrons. Essa explicação conceitual não restabelece um gabarito nem atribui uma causa à anulação, não informada no documento consultado."],"alternatives":{"A":"ATP é uma molécula de transferência de energia. Não exerce o papel de doador inicial de elétrons comparado ao H₂S.","B":"NADPH carrega poder redutor para etapas biossintéticas; não é a fonte inicial comparada à água nessa analogia.","C":"O₂ é liberado na fotossíntese oxigênica; não corresponde ao doador de elétrons H₂S descrito.","D":"Clorofila participa da absorção de luz e transferência de energia e elétrons, não substitui a fonte inicial de elétrons.","E":"Água é o doador de elétrons na fotossíntese oxigênica. Esta relação é explicação didática, não letra oficial de item anulado."},"takeaway":"Em questão anulada, estude o conceito sem inventar gabarito, pontuação ou motivo de anulação.","key":"natureza:N151","area":"natureza","year":2025,"number":123,"answer":"Anulada","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":true,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Potenciais: escurecimento e limpeza da prata","steps":["No escurecimento, a prata é oxidada a Ag₂S, enquanto O₂ se reduz. Use E° = E°redução(cátodo) − E°redução(ânodo).","Escurecimento: 1,23 − (−0,69) = 1,92 V. Na limpeza, Ag₂S se reduz e o alumínio se oxida: −0,69 − (−1,68) = 0,99 V.","O par é +1,92 V e +0,99 V, alternativa B. Coeficientes estequiométricos não multiplicam potenciais, que são grandezas intensivas."],"alternatives":{"A":"+0,54 V soma 1,23 a −0,69 em vez de subtrair o potencial do ânodo; +2,37 V também não é a diferença requerida.","B":"Apresenta as duas diferenças corretas: 1,92 V para formar sulfeto de prata e 0,99 V para reduzi-lo com alumínio.","C":"−0,15 V e +5,43 V não resultam das diferenças de potenciais pertinentes; não se multiplicam potenciais por coeficientes.","D":"+2,61 V e +1,29 V são incompatíveis com as diferenças entre os pares redox envolvidos nas duas etapas.","E":"O sinal negativo da limpeza contradiz a diferença positiva −0,69 − (−1,68); o primeiro valor também está errado."},"takeaway":"Balanceie elétrons para somar reações, mas não multiplique E° por coeficientes estequiométricos.","key":"natureza:N763","area":"natureza","year":2025,"number":124,"answer":"B","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Estequiometria com três gases e rendimento","steps":["Os 4,00 L são a soma de NH₃, CO₂ e vapor de água a 453 K. Pela equação ideal, ngás = PV/RT = 4/(0,082 × 453) ≈ 0,1077 mol.","Um mol de NH₄HCO₃ gera três mols gasosos. Com rendimento 80%, ngás = 3 × 0,80 × nreagente, logo nreagente ≈ 0,0449 mol.","A massa é 0,0449 × 79 ≈ 3,54 g, mais próxima de 3,5 g: B. Use kelvin e divida pela fração de rendimento para compensar a perda."],"alternatives":{"A":"2,3 g fica abaixo até da massa estequiométrica sem perdas, cerca de 2,84 g; não produz os 4 L requeridos.","B":"3,5 g aproxima 4 × 79/(0,082 × 453 × 3 × 0,80) ≈ 3,54 g.","C":"5,9 g não corresponde à relação de três gases com rendimento de 80% nas condições dadas.","D":"6,8 g superestima a massa: pela mesma equação produziria aproximadamente 7,7 L, acima dos 4 L.","E":"8,9 g também superestima a quantidade; o cálculo correto já inclui a água no estado gasoso entre os três produtos."},"takeaway":"Conte todos os produtos gasosos nas condições indicadas e aplique rendimento antes de converter mol em massa.","key":"natureza:N719","area":"natureza","year":2025,"number":125,"answer":"B","subject":"Química","topic":"Estequiometria e gases","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Velocidade do avião relativa ao ar","steps":["Converta 6 min para 0,1 h. A velocidade média necessária em relação ao solo é (200 Leste, 200 Norte, 10 cima) km/h.","Use vsolo = var + vvento. Adote Norte e cima positivos: o vento tem componentes (30, −20, −1).","Subtraindo: var = (200 − 30, 200 − (−20), 10 − (−1)) = (170, 220, 11) km/h: D."],"alternatives":{"A":"230 para Leste adiciona o vento em vez de compensá-lo; Sul e baixo também contrariam o deslocamento desejado.","B":"230, 180 e 9 resultam de somar o vento à velocidade desejada, em vez de calcular a velocidade relativa ao ar.","C":"A componente Oeste inverte o movimento horizontal requerido e as outras componentes ignoram o vento.","D":"170 Leste, 220 Norte e 11 cima compensam respectivamente os ventos a Leste, Sul e para baixo.","E":"A componente de 180 para Norte subtrai incorretamente o vento Sul; são necessários 220 para compensá-lo."},"takeaway":"Velocidade relativa: primeiro escreva a soma vetorial, depois isole a grandeza pedida com sinais consistentes.","key":"natureza:N374","area":"natureza","year":2025,"number":126,"answer":"D","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Enzima reduz energia de ativação","steps":["A enzima catalisa a transformação A → B e oferece um caminho com menor barreira energética.","Como reagentes, produtos e demais condições são os mesmos, as energias inicial e final não mudam. Muda a altura do pico da trajetória.","A linha pontilhada deve começar e terminar nos mesmos níveis da contínua e ter pico menor: gráfico C. O catalisador não altera ΔH nem o equilíbrio."],"alternatives":{"A":"A linha pontilhada começa em outro nível de energia para A; catalisar não altera a energia do reagente.","B":"A figura muda a energia final de B, o que não decorre da presença de uma enzima.","C":"Mantém os níveis inicial e final e reduz o pico pontilhado, representando menor energia de ativação.","D":"O pico pontilhado fica mais alto, representando aumento da barreira, contrário à ação catalítica.","E":"Muda tanto os níveis iniciais quanto os finais; não representa apenas um caminho alternativo catalisado."},"takeaway":"Catalisador muda a barreira e a velocidade, não o saldo energético entre reagente e produto.","key":"natureza:N823","area":"natureza","year":2025,"number":127,"answer":"C","subject":"Química","topic":"Cinética química","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Sensibilidade é a inclinação da reta","steps":["A relação é R(T) = A + BT. O coeficiente B = ΔR/ΔT mede quanto a resistência varia por grau.","Para perceber pequenas mudanças de temperatura, queremos maior variação de resistência para o mesmo ΔT: maior inclinação, não maior resistência absoluta.","Na figura, as retas dos sensores 2 e 5 têm as maiores inclinações. Portanto E. A reta 1 está alta, mas quase horizontal e pouco sensível."],"alternatives":{"A":"O sensor 2 é sensível, mas o 1 quase não varia com a temperatura; resistência alta não significa sensibilidade alta.","B":"1 e 3 têm inclinações menores que as retas 2 e 5, apesar de resistências absolutas relativamente altas.","C":"O sensor 3 não é um dos dois mais inclinados; a reta 5 varia mais por grau.","D":"O sensor 4 tem inclinação inferior à do 5 e, por isso, menor sensibilidade no gráfico.","E":"As retas 2 e 5 exibem maior ΔR para um mesmo ΔT, correspondendo às maiores sensibilidades."},"takeaway":"Para comparar sensibilidade de um sensor, procure a taxa de variação, não o valor no eixo vertical.","key":"natureza:N495","area":"natureza","year":2025,"number":128,"answer":"E","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Controle do hospedeiro intermediário","steps":["O quadro indica alta eficiência contra moluscos aquáticos adultos; contra platelmintos, o produto é ineficiente.","Caramujos do gênero Biomphalaria são hospedeiros intermediários do Schistosoma mansoni. Controlá-los pode interromper uma etapa do ciclo.","Assim, mesmo sem matar diretamente o verme, o ácido pode ajudar no controle da esquistossomose: A. O foco está no ciclo de transmissão."],"alternatives":{"A":"A alta eficiência contra moluscos aquáticos pode reduzir hospedeiros intermediários da esquistossomose.","B":"Febre amarela é transmitida por mosquitos; o quadro não mostra alta eficiência contra seu vetor.","C":"Coqueluche é uma infecção bacteriana e a bactéria causadora não foi identificada entre os testes de alta eficiência.","D":"O bacilo de Koch é o agente da tuberculose, mas a eficiência registrada contra ele é média, inferior à observada em moluscos.","E":"Aedes aegypti transmite dengue, porém o produto teve baixa eficiência contra suas larvas."},"takeaway":"Uma doença pode ser controlada agindo sobre vetor ou hospedeiro intermediário, sem atacar diretamente o agente etiológico.","key":"natureza:N267","area":"natureza","year":2025,"number":129,"answer":"A","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Resistor em série para reduzir a tensão","steps":["Se a tensão nominal no aparelho é U, a fonte entrega 1,2U. O resistor deve consumir a diferença, 0,2U, mantendo U no aparelho.","Isso exige ligação em série: a mesma corrente percorre RC e RP. Como I = U/RC, temos RP = 0,2U/I = 0,2RC.","A configuração em série com RP = 0,2RC é E. Em paralelo, o aparelho receberia toda a tensão excessiva da fonte."],"alternatives":{"A":"Embora o valor 0,2RC seja adequado em série, a montagem em paralelo não reduz a tensão aplicada ao aparelho.","B":"A ligação paralela mantém a sobretensão, e 1,2RC não é o valor de queda de tensão necessário.","C":"A série é adequada, mas RP = 1,2RC retiraria uma fração muito maior da tensão do que a necessária.","D":"RP = 2,2RC em série também provocaria queda excessiva, impedindo a tensão nominal no aparelho.","E":"Em série, RP = 0,2RC dissipa 0,2U na corrente nominal, deixando U no equipamento."},"takeaway":"Divisor resistivo exige série. Compare as quedas de tensão na mesma corrente, não apenas a porcentagem da fonte.","key":"natureza:N324","area":"natureza","year":2025,"number":130,"answer":"E","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Aluminotermia com excesso de reagente","steps":["Converta a massa desejada: 9,3 kg = 9 300 g. Assim, nNb = 9 300/93 = 100 mol.","A equação indica 10 mol de Al para 6 mol de Nb. A massa estequiométrica de Al é 100 × (10/6) × 27 = 4 500 g = 4,5 kg.","Adicione os 10% de excesso: 4,5 × 1,10 = 4,95 kg, aproximadamente 5,0 kg: E. O excesso é aplicado à massa estequiométrica de alumínio."],"alternatives":{"A":"2,7 kg corresponderiam a 100 mol de Al, desconsiderando a razão 10/6 entre alumínio e nióbio.","B":"3,0 kg não satisfaz a proporção molar 10/6 acrescida de 10%; fica abaixo da massa estequiométrica.","C":"4,1 kg fica abaixo de 4,5 kg, o mínimo estequiométrico; excesso não pode reduzir a massa necessária.","D":"4,5 kg é a massa calculada sem os 10% adicionais exigidos pelo processo.","E":"5,0 kg aproxima 4,95 kg, incluindo corretamente a proporção da reação e o excesso de alumínio."},"takeaway":"Rendimento, pureza e excesso são ajustes diferentes: aqui o rendimento é 100%, mas o reagente entra com 10% extra.","key":"natureza:N720","area":"natureza","year":2025,"number":131,"answer":"E","subject":"Química","topic":"Estequiometria e gases","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Questão anulada: soma de intensidades sonoras","steps":["O gabarito oficial registra a questão como anulada. Não existe letra oficial e nenhuma das opções deve ser contada como acerto ou erro.","Como exercício conceitual, níveis em decibéis não se somam diretamente. Sob a hipótese de intensidades médias aditivas, multiplicar I por N acrescenta 10 log₁₀N ao nível.","Com N = 10 000, o acréscimo seria 40 dB, e 100 + 40 = 140 dB nesse modelo idealizado. Isso não restaura um gabarito nem explica a causa oficial da anulação, que não é fornecida no documento."],"alternatives":{"A":"60 dB é inferior ao nível individual dado; não representa a adição de intensidades positivas no modelo idealizado.","B":"104 dB adiciona 4 em vez de 10 × 4 ao nível individual, confundindo logaritmo e fator da escala.","C":"140 dB é o resultado do modelo didático de soma de intensidades; a questão, porém, está oficialmente anulada e não tem letra válida.","D":"400 dB não resulta de 100 + 10 log₁₀(10 000); multiplicar níveis não corresponde a somar intensidades.","E":"800 dB também não decorre da relação logarítmica dada. Nenhuma alternativa é atribuída como oficial neste item anulado."},"takeaway":"Decibéis usam escala logarítmica; e um resultado de estudo não transforma questão anulada em questão com gabarito.","key":"natureza:N453","area":"natureza","year":2025,"number":132,"answer":"Anulada","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":true,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Camada externa de um filtro óleo–água","steps":["O dispositivo tem malha de aço, polímero, sílica, outro polímero e, na superfície externa, surfactante.","A água e o óleo encontram primeiro o revestimento de surfactante, cujas cadeias fluoradas conferem a propriedade superficial de rejeitar o óleo.","É nessa camada externa que ocorre a retenção na separação descrita: A. Não atribua à malha de suporte a seletividade química da superfície."],"alternatives":{"A":"O surfactante constitui o revestimento externo responsável pela interação superficial que impede a passagem do óleo.","B":"O polímero superior sustenta a montagem, mas está recoberto pelo surfactante que fornece a seletividade superficial.","C":"As nanopartículas contribuem para a estrutura e textura; não são a camada externa indicada como retentora do óleo.","D":"O polímero inferior está abaixo da sílica, distante da interface externa que encontra a mistura.","E":"A malha de aço dá suporte físico ao dispositivo; sua presença não explica a seletividade do revestimento."},"takeaway":"Em materiais multicamadas, distinga suporte mecânico, textura e química da superfície em contato com a mistura.","key":"natureza:N621","area":"natureza","year":2025,"number":133,"answer":"A","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Grupos OH e interação com água","steps":["As moléculas têm esqueletos orgânicos semelhantes e predominantemente apolares, mas diferem nos grupos oxigenados.","O estriol apresenta três grupos OH. Eles podem doar e aceitar ligações de hidrogênio, ampliando as interações com a água em comparação aos demais compostos mostrados.","No conjunto comparado, o estriol tem a maior afinidade aquosa: B. A comparação depende do balanço entre região apolar e grupos polares, não apenas do nome do hormônio."],"alternatives":{"A":"O estradiol apresenta dois OH, um a menos que o estriol, oferecendo menos grupos de interação desse tipo com a água.","B":"O estriol possui três hidroxilas no esqueleto apresentado, favorecendo mais ligações de hidrogênio com a água.","C":"A estrona apresenta uma hidroxila e uma carbonila; não tem os três grupos OH do estriol.","D":"O novestrol possui dois OH e uma porção carbônica adicional; não supera a afinidade aquosa do estriol nessa comparação.","E":"A noretindrona tem uma hidroxila e uma carbonila, além do esqueleto apolar, sem os três OH do estriol."},"takeaway":"Compare grupos capazes de formar ligações de hidrogênio junto com o tamanho da região apolar.","key":"natureza:N832","area":"natureza","year":2025,"number":134,"answer":"B","subject":"Química","topic":"Ligações e interações intermoleculares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Frequência maior, comprimento de onda menor","steps":["O espectro inicial tem máximo em torno de 600 nm, correspondente à coloração vermelho-laranja.","O enunciado afirma que a frequência emitida aumenta. Como c = λf, a frequência maior implica menor comprimento de onda.","O máximo final deve deslocar-se para a esquerda, em direção ao verde. O gráfico A mostra esse deslocamento; não basta mudar só a altura do pico."],"alternatives":{"A":"A linha final pontilhada tem máximo em comprimento de onda menor que o inicial, como exige o aumento de frequência.","B":"O pico pontilhado se desloca para comprimentos de onda maiores, correspondente a frequência menor, não maior.","C":"O pico permanece aproximadamente na mesma posição; mudar sua altura representa intensidade, não a mudança de frequência pedida.","D":"Também preserva a posição do máximo, alterando principalmente a intensidade, sem a mudança espectral solicitada.","E":"Os espectros praticamente coincidem, não representando a evolução de vermelho-laranja para verde descrita."},"takeaway":"No eixo de comprimento de onda, azul/verde ficam à esquerda de vermelho; frequência e comprimento variam inversamente.","key":"natureza:N541","area":"natureza","year":2025,"number":135,"answer":"A","subject":"Física","topic":"Óptica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2025.pdf","sha256":"9e2d470af35378df532173414ec7077c3ce4df38c084a5f1258579fdf9270aef","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2025.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
